style.css:
@-moz-document domain("ebay.com") {
/* Fondo general oscuro */
  body, #mainContent, .app__container, .vip-content {
    background-color: #121212 !important;
    color: #ffffff !important;
  }

  /* Secciones con fondo blanco */
  .app-container, .app__container, .vip-content, .about-this-item,
  .about-seller, .seller-feedback, .item-specs {
    background-color: #1e1e1e !important;
    color: #ffffff !important;
  }

  /* Enlaces */
  a {
    color: #4aa3ff !important;
  }

  /* Texto gris claro que no se leía */
  .s-item__price, .s-item__title, .s-item__location,
  .about-seller p, .seller-feedback p {
    color: #ffffff !important;
  }

  /* Cuadros de información */
  .x-overlay, .x-overlay-content, .shipping-section, 
  .returns-section, .payments-section, .seller-section {
    background-color: #1e1e1e !important;
    color: #ffffff !important;
  }

  /* Fondos de input y selección */
  input, select, textarea {
    background-color: #222 !important;
    color: #ffffff !important;
    border: 1px solid #444 !important;
  }

  /* Botones */
  button, .btn, .s-item__cta, .action-button {
    background-color: #0078ff !important;
    color: #ffffff !important;
  }

  /* Evita invertir imágenes y botones importantes */
  img, svg, .btn--primary {
    filter: none !important;
  }
}
